const fs=require('node:fs'),path=require('node:path');
const sharp=require(process.env.YAMB_SHARP_PATH||'sharp');
const root=path.resolve(__dirname,'..'),raw=path.join(root,'tmp/emulator-treasury-2026-10-28'),out=path.join(root,'docs/theme-visual-audit/emulator-treasury-2026-10-28');
const themes=['dark','light','medium','winter','neon','amethyst','easter','desert','moon','severna'];
const names=['Zelena','Svetlo zlato','Trula višnja','Plavi okean','Neon Cyber','Kraljevski ametist','Vaskršnja','Pustinjsko staklo','Mesečev sjaj','Severna maglina'];
const chosen={
 dark:['dark-trophies-ready','dark-skins','dark-effects','dark-effects-bottom','dark-effects-cosmos','dark-themes-first'],
 light:['light-trophies','light-skins','light-effects','light-effects-middle','light-effects-cosmos','light-themes'],
 medium:['medium-trophies','medium-skins','medium-effects','medium-effects-middle','medium-effects-cosmos','medium-themes'],
 winter:['winter-trophies','winter-skins','winter-effects','winter-effects-middle','winter-effects-cosmos','winter-themes'],
 neon:['neon-trophies-top','neon-skins','neon-effects','neon-effects-middle','neon-effects-cosmos','neon-themes'],
 amethyst:['amethyst-trophies','amethyst-skins','amethyst-effects','amethyst-effects-middle','amethyst-effects-cosmos','amethyst-themes'],
 easter:['easter-trophies-upper','easter-skins','easter-effects-ready','easter-effects-middle','easter-effects-cosmos','easter-themes'],
 desert:['desert-trophies-first','desert-skins','desert-effects','desert-effects-middle','desert-effects-cosmos','desert-themes'],
 moon:['moon-trophies-upper2','moon-skins','moon-effects','moon-effects-middle','moon-effects-cosmos','moon-themes'],
 severna:['severna-trophies-upper2','severna-skins','severna-effects','severna-effects-middle','severna-effects-cosmos','severna-themes']
};
const titles=['Trofeji / početak','Skinovi / klasika','Efekti / proslave','Efekti / atmosfera','Efekti / kosmos','Teme / katalog'];
const entries=themes.flatMap((theme,i)=>chosen[theme].map((file,k)=>({theme,file,title:`${names[i]} — ${titles[k]}`})));
entries.push({theme:'extra',file:'light-from-treasury',title:'Promena teme — nepotpuni prvi PNG prikaz'},
 {theme:'extra',file:'severna-themes-loading',title:'Severna — nova paleta uz prethodne tab ikone tokom učitavanja'},
 {theme:'extra',file:'easter-effects',title:'Vaskršnja — prazni pregledi tokom prvog učitavanja'},
 {theme:'extra',file:'dark-theme-restored-ready',title:'Završno vraćanje Zelene u Riznici'},
 {theme:'extra',file:'dark-main-restored-original',title:'Zelena / originalna rezolucija emulatora'});
const inventory=JSON.parse(fs.readFileSync(path.join(root,'tmp/treasury-active-inventory-20261028.json'),'utf8'));
const runtime=JSON.parse(fs.readFileSync(path.join(root,'tmp/treasury-layout-runtime/report.json'),'utf8'));
if(runtime.rows.length!==120)throw Error('120 successful local cases required');
const results=themes.map((theme,i)=>({theme,name:names[i],status:'Osnovni prolaz četiri taba pregledan; lokalne dorade čekaju Android potvrdu posle deploya.',visualPng:'U snimljenim stanjima odgovarajući identiteti teme. Nije potrebna nova PNG zamena u ovom prolazu.',findings:'R20: tematsko zaglavlje, statusne podloge i nagradna kontrola; jednaka Green težina i razmak slova. R14/R15 ranije lokalno ispravljeni, objavljena verzija još pokazuje učitavanje i stara stanja.',inventory:inventory.results.find(r=>r.theme===theme),activePngRoles:inventory.inventory.find(r=>r.theme===theme).roles,evidence:chosen[theme].map(f=>f+'.jpg')}));
const report={date:'2026-10-28',room:'Riznica',scope:'Stvarni Android emulator, logički 360×780, svih deset tema: Trofeji (prve kategorije), Skinovi (prva četiri klasična skina), Efekti (proslave, atmosfera, kosmos), Teme (različiti delovi kataloga).',deployment:'Galerija prikazuje postojeću objavljenu verziju. Nove lokalne CSS/JS dorade nisu commitovane niti deployovane.',
 inventoryNote:'116 semantičkih katalog-uloga po temi: 55 tematskih + 61 zajednička (48 skinova, 10 odobrenih pregleda tema i 3 namerno univerzalna efekta: ice_age, balkan, dragon_fire). Raniji izveštaj 58+58 proveravao je i tri tematska originala koja više nisu aktivne sličice. Sada se koriste stvarne putanje getTreasuryEffectPreviewSource i quality resolver. Broj uloga nije broj istovremeno vidljivih ili preuzetih slika; skinovi uz temu zavise od vlasništva.',
 localChanges:{R20:'Zaglavlja devet tema koriste sopstveni card-fill/ink. Statusi i nagradno dugme koriste čitljivu tematsku površinu bez jarke univerzalne zelene; Green statusi koriste postojeću Clay inset površinu. Težina naslova 850 i razmak .025em prate Green, težina akcija/statusa 700; uklonjen nasleđeni razmak naslova kartica i zamućujuće tekstualne senke. Dimenzije/funkcije i PNG identiteti ostaju.',css:'www/theme-treasury-room.css?v=8',prior:'R14: priprema/decode pre aktiviranja teme iz Riznice; R15: Easter tabovi i Light zaglavlje. Sve čeka potvrdu posle deploya.'},
 tests:{static:'PASS: 116 aktivnih semantičkih uloga × 10 tema, postojeći PNG fajlovi i različiti tematski hashovi; 26 trofeja/48 skinova/16 efekata/10 tema. Hash različitost sama ne dokazuje jedinstven vizuelni dizajn.',runtime:'PASS: 120 izolovanih Chromium slučajeva — 10 tema × 4 taba × 320×568, 360×780, 412×915. Stvarni ShopManager i CSS, sintetičko vlasništvo; izračunate Green mere/tipografija, bez horizontalnog izlaska; boje zaglavlja/statusa iz palete.',runtimeEvidence:'local-layout-report.json',contrast:'Najmanji provereni paletni par 4,85:1; nove neprozirne statusne podloge devet tema najmanje 6,12:1. Nije merenje svakog piksela preko pozadine.',fontLimit:'Montserrat je deklarisan; izolovani offline test može koristiti Arial fallback. Android snimci su odvojen dokaz.'},
 switching:'Svih devet direktnih izbora već posedovanih tema iz Riznice uspelo je iz prvog pokušaja u ovom prolazu; vraćanje Zelene takođe. Tokom prvih sekundi vidljive su stare ili delimično učitane ikone. Ovo nije dokaz trenutnog hladnog prelaska niti potvrda lokalnog decode popravka.',
 safety:'Nema pokrenute partije, kupovine, nagradne reklame, preuzimanja nagrade, prihvaćenog duela ili poslate poruke. Birane su samo već posedovane teme. Novi poziv Lidije je nestao sam dok je traženo odobrenje; nije kliknuto odbijanje/prihvatanje.',restoration:'Vraćena Zelena kroz vidljivi UI; wm size/density resetovani na originalnih 1440×3120 /560dpi. Emulator otvoren i prijavljen.',
 limits:['Nije sada vizuelno pregledana svaka od 26 trofejnih, 48 skin ili 16 efektnih kartica u svakoj temi; njihov inventar i putanje provereni su statički.','Nema nove provere stvarne kupovine, potvrda/grešaka, reklamnih nagrada ili otključavanja skinova nalogom.','Nisu aktivirane žive animacije efekata niti novi skinovi. Dodir trofejne kartice u Green nije otvorio zaseban detalj; takav modal nije označen kao pregledan.','Screenshot ne potvrđuje tačno trajanje intra, fps, prvi mrežni transfer, svaki jezik ili fizički Samsung S25.','Sve lokalne dorade zahtevaju korisnikov deploy i novi Android pregled. Ostala retka stanja i preostalih šest soba ostaju za nastavak.'],results,entries};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function main(){
 fs.mkdirSync(out,{recursive:true});
 fs.copyFileSync(path.join(root,'tmp/treasury-layout-runtime/report.json'),path.join(out,'local-layout-report.json'));
 for(const e of entries)await sharp(path.join(raw,e.file+'.png')).resize({width:540}).jpeg({quality:88,chromaSubsampling:'4:4:4'}).toFile(path.join(out,e.file+'.jpg'));
 fs.writeFileSync(path.join(out,'report.json'),JSON.stringify(report,null,2)+'\n');
 const card=e=>`<article><h3>${esc(e.title)}</h3><a href="${e.file}.jpg"><img loading="lazy" src="${e.file}.jpg" alt="${esc(e.title)}"></a></article>`;
 fs.writeFileSync(path.join(out,'index.html'),`<!doctype html><html lang="sr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Riznica — emulator 28.10.</title><style>*{box-sizing:border-box}body{font:16px/1.5 system-ui;background:#14232e;color:#edf5fc;margin:0;padding:24px}main{max-width:1500px;margin:auto}a{color:#afe4ff}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}article{background:#233847;border:1px solid #7997a9;border-radius:12px;padding:12px}img{width:100%;height:auto}h3{font-size:17px}nav{display:flex;gap:12px;flex-wrap:wrap}</style><main><h1>Riznica — osnovni pregled deset tema</h1><p>${esc(report.scope)}</p><p><b>${esc(report.deployment)}</b></p><nav><a href="report.json">Aktivne putanje i rezultati</a><a href="local-layout-report.json">Lokalni CSS test</a>${results.map(r=>`<a href="#${r.theme}">${esc(r.name)}</a>`).join('')}</nav><p>${esc(report.inventoryNote)}</p><h2>Lokalne dorade koje Android snimci još ne potvrđuju</h2><p>${esc(report.localChanges.R20)}</p><p>${esc(report.tests.runtime)}</p><p>${esc(report.tests.fontLimit)}</p><h2>Granice provere</h2><ul>${report.limits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${results.map(r=>`<section id="${r.theme}"><h2>${esc(r.name)}</h2><p>${esc(r.status)}</p><div class="grid">${entries.filter(e=>e.theme===r.theme).map(card).join('')}</div></section>`).join('')}<h2>Učitavanje i vraćanje emulatora</h2><p>${esc(report.switching)}</p><div class="grid">${entries.filter(e=>e.theme==='extra').map(card).join('')}</div><p>${esc(report.safety)}</p><p>${esc(report.restoration)}</p></main></html>`);
 console.log(`Treasury: ${results.length} themes, ${entries.length} scoped Android screenshots; 116 active roles/theme.`);
}
main().catch(e=>{console.error(e);process.exitCode=1;});
